/** 역경 id → 아이콘 */
const AGENDA_ICON: Record<number, string> = {
  1: 'lotus',
  2: 'whirlwind',
  3: 'plug',
  4: 'pig',
  5: 'grapes',
  6: 'scroll-unfurled',
  7: 'bull',
  8: 'mermaid',
  9: 'vortex',
  10: 'ogre',
  11: 'big-wave',
  12: 'barn-owl',
  13: 'spartan-helmet',
  14: 'sea-serpent',
  15: 'hydra',
  16: 'cyclops',
  17: 'volcano',
  18: 'crown',
  19: 'discobolus',
  20: 'island',
  21: 'hades-symbol',
  22: 'lightning-branches',
};

const CARD_ICON: Record<CardId, string> = {
  basic: 'plain-dagger',
  blitz: 'trident',
  practice: 'thrown-spear',
  promo: 'bow-arrow',
  hold: 'crossed-chains',
};

export function glyph(name: string, cls = ''): string {
  return `<svg class="glyph${cls ? ` ${cls}` : ''}" viewBox="0 0 512 512" aria-hidden="true">${PATHS[name] ?? ''}</svg>`;
}

export const agendaGlyph = (id: number, cls = ''): string => glyph(AGENDA_ICON[id], cls);
export const cardGlyph = (id: CardId, cls = ''): string => glyph(CARD_ICON[id], cls);
